create type public.app_role as enum ('admin','user');
create table public.user_roles(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role public.app_role not null, unique(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create policy own_roles on public.user_roles for select to authenticated using(user_id=auth.uid());
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
create table public.site_content(key text primary key,value jsonb not null);
grant select on public.site_content to anon; grant select,insert,update on public.site_content to authenticated; grant all on public.site_content to service_role;
alter table public.site_content enable row level security;
create policy public_content on public.site_content for select to anon,authenticated using(true);
create policy admin_content on public.site_content for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create table public.contact_submissions(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),name text not null check(length(name) between 1 and 100),email text not null check(length(email)<=255),topic text not null,message text not null check(length(message) between 10 and 2000));
grant select on public.contact_submissions to authenticated; grant all on public.contact_submissions to service_role;
alter table public.contact_submissions enable row level security;
create policy admin_inbox on public.contact_submissions for select to authenticated using(public.has_role(auth.uid(),'admin'));
create table public.contact_limits(email_hash text primary key,last_sent timestamptz not null default now());
grant all on public.contact_limits to service_role;
alter table public.contact_limits enable row level security;
